UPDATE categories SET text_en = '[Apartments for sale](/oglasi/nekretnine/stanovi/prodaja), [long-term rent](/oglasi/nekretnine/stanovi/izdavanje) and [daily rent](/oglasi/nekretnine/stanovi/na-dan) in [Belgrade](/oglasi/nekretnine/stanovi/prodaja/beograd), [Novi Sad](/oglasi/nekretnine/stanovi/prodaja/novi-sad), Niš and other cities: studios, one-, two- and three-bedroom flats, new builds and flats directly from owners. In Belgrade and Novi Sad you can also choose the district.

