UPDATE categories SET text_sr = 'Auto delovi, novi i polovni: delovi motora i menjača, karoserija, [svetla](/oglasi/vozila/auto-delovi/svetla), akumulatori, delovi trapa i enterijera za sve marke. Mnogi otpadi i prodavnice delova oglašavaju se ovde.

